    k %= len(arr)
    return arr[k:] + arr[:k]

import tokenize

def transform_integers_to_hex(file_path: str) -> str:
    with open(file_path, 'r') as f:
        source_code = f.read()

    tokens = tokenize.generate_tokens(source_code)
    new_tokens = []

    for token_type, token_string, start_pos, end_pos, line_number, column_number in tokens:
        if token_type == tokenize.NUMBER:
            if token_string[0] == '-':
                new_tokens.append((token_type, f'-0x{token_string[1:]}', start_pos, end_pos, line_number, column_number))
            else:
                new_tokens.append((token_type, f'0x{token_string}', start_pos, end_pos, line_number, column_number))
        else:
            new_tokens.append((token_type, token_string, start_pos, end_pos, line_number, column_number))

    modified_source_code = tokenize.untokenize(new_tokens)
    return modified_source_code

def kthSmallest(arr, k):
    arr.sort()
    return arr[k - 1]

def find_longest_unique_substring(word):
    if not word:
        return 0

    max_length = 0
    seen = {}
    start = 0

    for i, char in enumerate(word):
        if char in seen and start <= seen[char]:
            start = seen[char] + 1
        seen[char] = i
        max_length = max(max_length, i - start + 1)

    return max_length

from itertools import permutations

def find_words(s, words):
    perms = set(permutations(s))
    valid_words = set()

    for perm in perms:
        word = ''.join(perm)
        if word in words:
            valid_words.add(word)

    return valid_words

def is_visible(heights):
    max_height = -1
    visible = []

    for height in heights[::-1]:
        if height > max_height:
            max_height = height
        else:
            visible.append(max_height == height)
            max_height = height

    # Add the last building's visibility
    visible.append(max_height == heights[-1])

    return visible

def min_sessions(tasks, session_time):
    tasks.sort(reverse=True)
    sessions = 0
    current_time = 0

    for task in tasks:
        if current_time + task > session_time:
            sessions += 1
            current_time = task
        else:
            current_time += task

    if current_time > 0:
        sessions += 1

    return sessions

def find_student_by_mark(marks: List[int], target_mark: int) -> int:
    if not marks:
        return -1

    return next((i for i, mark in enumerate(marks) if mark == target_mark), -1)
